registry = odoo.modules.registry.Registry('said_express')
updated_count = 0

with registry.cursor() as cr:
    env = api.Environment(cr, SUPERUSER_ID, {})

    for code, b64_data in matched_products.items():
        products = env['product.product'].search([
            '|', '|', ('default_code', '=', code), ('barcode', '=', code), ('default_code', 'ilike', code)
        ])
        
        if products:
            for p in products:
                p.write({
                    'image_1920': b64_data,
                    'default_code': p.default_code or code,
                })
                updated_count += 1
                print(f"SUCCESS: Updated product {p.name} (Code: {code}) with 100% PURE RAW PHOTO!")

    cr.commit()
    print(f"COMPLETED: Updated {updated_count} products in Odoo with 100% PURE RAW PHOTOS (Zero text, Zero yellow borders)!")
